from jsonb_to_recordset($json$[{"id":"che-st-126","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A gas burette delivers 2.24 L of hydrogen, measured at STP. The amount of $\\mathrm{H_2}$ collected is","options":["0.010 mol","0.10 mol","1.0 mol","2.0 mol"],"answer_index":1,"explanation":"Moles $= 2.24 / 22.4 = 0.10$ mol at STP.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-127","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A sealed ampoule contains $3.011 \\times 10^{23}$ molecules of dinitrogen. The mass of that $\\mathrm{N_2}$ sample is","options":["7 g","14 g","28 g","56 g"],"answer_index":1,"explanation":"The count is 0.50 mol; mass $= 0.50 \\times 28 = 14$ g.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-128","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Eight grams of dioxygen and seven grams of dinitrogen are compared atom by atom. The two samples contain","options":["equal numbers of molecules and equal numbers of atoms","equal numbers of molecules but different numbers of atoms","different numbers of molecules but equal numbers of atoms","neither equal molecules nor equal atoms"],"answer_index":0,"explanation":"Both are 0.25 mol of diatomic molecules, so both have $0.25\\,N_A$ molecules and $0.50\\,N_A$ atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-129","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A 0.25 mol sample of $\\mathrm{Ca_3(PO_4)_2}$ is examined. The number of oxygen atoms in the sample is","options":["$0.25\\,N_A$","$1.00\\,N_A$","$2.00\\,N_A$","$8.00\\,N_A$"],"answer_index":2,"explanation":"Each formula unit has 8 oxygen atoms, so $0.25 \\times 8 = 2.00$ mol of O atoms, i.e. $2.00\\,N_A$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-130","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Among 8 g $\\mathrm{O_2}$, 7 g $\\mathrm{N_2}$, 4 g $\\mathrm{He}$ and 9 g $\\mathrm{H_2O}$, the largest number of atoms is present in","options":["8 g $\\mathrm{O_2}$","7 g $\\mathrm{N_2}$","4 g $\\mathrm{He}$","9 g $\\mathrm{H_2O}$"],"answer_index":3,"explanation":"Atom amounts are 0.50, 0.50, 1.0 and 1.5 mol respectively; 9 g water therefore has the most atoms.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"mole-avogadro","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-131","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Using H = 1, S = 32 and O = 16, the molar mass of sulphuric acid $\\mathrm{H_2SO_4}$ is","options":["82 g mol$^{-1}$","98 g mol$^{-1}$","114 g mol$^{-1}$","64 g mol$^{-1}$"],"answer_index":1,"explanation":"$2(1) + 32 + 4(16) = 98$ g mol$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-132","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Calcium carbonate $\\mathrm{CaCO_3}$ (Ca = 40, C = 12, O = 16) has a formula mass of","options":["50 u","84 u","100 u","116 u"],"answer_index":2,"explanation":"$40 + 12 + 48 = 100$ u.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-133","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The percentage by mass of oxygen in water is closest to","options":["11.1%","50%","88.9%","94.1%"],"answer_index":2,"explanation":"Oxygen contributes 16 of the 18 g in one mole of $\\mathrm{H_2O}$, i.e. $16/18 \\times 100 = 88.9\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-134","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In methane, the mass percent of carbon (C = 12, H = 1) works out to","options":["25%","50%","75%","80%"],"answer_index":2,"explanation":"Carbon is 12 g in 16 g of $\\mathrm{CH_4}$, so $12/16 \\times 100 = 75\\%$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-135","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"Carbon dioxide is assigned a molecular mass of 44 u because that value equals","options":["12 + 16","12 + 2(16)","2(12) + 16","12 + 32 + 16"],"answer_index":1,"explanation":"One C and two O atoms give $12 + 32 = 44$ u.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"molar-mass-percent","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
